def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(src, dst):
        return [sgn(dst[0] - src[0]), sgn(dst[1] - src[1])]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    self_pos = observation.get("self_position", [0, 0])
    opp_pos = observation.get("opponent_position", [0, 0])
    sx, sy = self_pos[0], self_pos[1]
    ox, oy = opp_pos[0], opp_pos[1]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = []
        if gw and gh:
            corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
        if not corners:
            return [-sgn(ox - sx), -sgn(oy - sy)]
        target = max(corners, key=lambda c: dist(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = min(targets, key=lambda item: dist(item, self_pos))
            return step_toward(self_pos, best)
        center = observation.get("grid_center")
        if center:
            return step_toward(self_pos, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_cells") or []
    if resources:
        opp_bias = []
        for r in resources:
            try:
                opp_bias.append((dist(r, self_pos), dist(r, opp_pos), r))
            except Exception:
                pass
        if opp_bias:
            best = min(opp_bias, key=lambda t: (t[0], t[1]))
            return step_toward(self_pos, best[2])

    if ox != sx or oy != sy:
        return step_toward(self_pos, opp_pos)
    return [0, 0]

